                    new THREE.MeshLambertMaterial({ color: 0x666666 })
                );
                button.rotation.x = Math.PI / 2;
                button.position.set(-0.3 + (i % 2) * 0.4, 0.5 - Math.floor(i/2) * 0.4, 0.1);
                this.destinationPanel.add(button);
                this.buttonRefs.push(button);
            }

            // In-car indicator above doors (looking back at passengers)
            const inCarIndicator = new THREE.Mesh(
                new THREE.PlaneGeometry(0.6, 0.6),
                new THREE.MeshLambertMaterial({ 
                    color: 0x888888,
                    depthWrite: false 
                })
            );
            inCarIndicator.position.set(0, this.carHeight - 0.3, -this.carDepth/2 + 0.1);
            this.destinationPanel.add(inCarIndicator);

            this.destinationPanel.position.set(0, this.carHeight/2, -this.carDepth/2 + 0.5);
            this.carGroup.add(this.destinationPanel);

            // Add car group to scene
            scene.add(this.carGroup);

            // Update initial positions and indicators
            this.updateCarPosition();
            this.updateIndicators();
        }

        updateCarPosition() {
            // Sync car position with logic.currentFloor
            this.carGroup.position.y = this.logic.currentFloor * this.world.FLOOR_HEIGHT;
        }

        updateDoors() {
            const isOpening = this.logic.state === this.logic.DOOR_OPENING;
            const isClosing = this.logic.state === this.logic.DOOR_CLOSING;
            const isOpen = this.logic.state === this.logic.DOOR_OPEN;

            // Sliding doors: closed at x=0, open when moved outward
            const openOffset = (this.carWidth / 2) - 0.1; // Small gap when closed

            if (isOpening || isClosing) {
                // Animate door movement based on timer
                const speed = isOpening ? 0.5 : 0.5;
                this.leftDoor.position.x = -openOffset * (isOpen ? 1 : 0);
                this.rightDoor.position.x = openOffset * (isOpen ? 1 : 0);
            } else if (isOpen) {
                // Fully open
                this.leftDoor.position.x = -openOffset;
                this.rightDoor.position.x = openOffset;
            } else {
                // Closed
                this.leftDoor.position.x = -0.1;
                this.rightDoor.position.x = 0.1;
            }
        }

        updateIndicators() {
            // Update building-side call panel lamps and indicators
            for (const floor of this.world.floors) {
                if (floor.callPanelMesh) {
                    const panel = floor.callPanelMesh;

                    // Up arrow lamp
                    panel.userData.setUp(this.logic.upCalls.has(floor.floorNumber) && 
                        this.logic.direction !== -1);

                    // Down arrow lamp
                    panel.userData.setDown(this.logic.downCalls.has(floor.floorNumber) && 
                        this.logic.direction !== 1);

                    // Floor indicator (car's current floor and direction)
                    const dir = this.logic.direction;
                    let text = Math.round(this.logic.currentFloor).toString();
                    if (dir !== 0) text += dir > 0 ? '^' : 'v';
                    panel.userData.setIndicator(text);
                }

                // Update shaft indicator above doors
                if (floor.shaftIndicatorMesh) {
                    const ind = floor.shaftIndicatorMesh;
                    const dir = this.logic.direction;
                    let text = Math.round(this.logic.currentFloor).toString();
                    if (dir !== 0) text += dir > 0 ? '^' : 'v';
                    ind.userData.updateDisplay(Math.round(this.logic.currentFloor), dir);
                }
            }

            // Update in-car destination buttons
            for (const floor of this.logic.destinations) {
                if (this.buttonRefs[floor]) {
                    this.buttonRefs[floor].material.color.setHex(0x00ff00); // Green when pressed
                }
            }

            // Reset other buttons
            for (let i = 0; i < this.buttonRefs.length; i++) {
                if (!this.logic.destinations.has(i)) {
                    this.buttonRefs[i].material.color.setHex(0x666666);
                }
            }
        }

        // Public API - mirrors ElevatorLogic methods
        callUp(floor) { this.logic.callUp(floor); }
        callDown(floor) { this.logic.callDown(floor); }
        pressDestination(floor) { this.logic.pressDestination(floor); }
        isAcceptingAt(floor, direction) { return this.logic.isAcceptingAt(floor, direction); }
        currentCapacityFree() { return this.logic.currentCapacityFree(); }

        reserveBoardingSpot(person) {
            const spot = this.logic.reserveBoardingSpot(person);
            if (spot) {
                // Convert car-local spot position to world position for boarding
                person.boardingSpotIndex = spot.index;
                const worldPos = new THREE.Vector3(spot.x, spot.y, spot.z);
                worldPos.applyMatrix4(this.carGroup.matrixWorld);
                return worldPos;
            }
            return null;
        }

        completeBoard(person) { this.logic.completeBoard(person); }
        registerDisembark(person) { this.logic.registerDisembark(person); }
        completeDisembark(person) { this.logic.completeDisembark(person); }

        tick(dt) {
            // Advance logic state machine
            this.logic.tick(dt);

            // Update visual components
            this.updateCarPosition();
            this.updateDoors();
            this.updateIndicators();
        }

        reset() {
            this.logic.reset();
            this.carGroup.position.y = 0;
            this.leftDoor.position.x = -0.1;
            this.rightDoor.position.x = 0.1;
        }

        // Expose state for HUD
        getState() {
            return this.logic.getState();
        }
    }

    window.Elevator = Elevator;
})();

// person.js - Person mesh factory + walk/sit animation

(function() {
    // Color palettes for visual distinction
    const BODY_COLORS = [0xff6b6b, 0x4ecdc4, 0x45b7d1, 0xf7b731, 0xa29bfe, 0xe17055];
    const SKIN_COLORS = [0xf8c4a7, 0xffdbac, 0xd1a68a, 0x8d5524, 0xc68642, 0xeebb99];
    const LEG_COLORS = [0x34495e, 0x2c3e50, 0x7f8c8d, 0x95a5a6, 0x3498db, 0x1abc9c];

    function createPerson(options) {
        options = options || {};
        const bodyColor = options.bodyColor || BODY_COLORS[Math.floor(Math.random() * BODY_COLORS.length)];
        const skinColor = options.skinColor || SKIN_COLORS[Math.floor(Math.random() * SKIN_COLORS.length)];
        const legColor = options.legColor || LEG_COLORS[Math.floor(Math.random() * LEG_COLORS.length)];

        const person = new THREE.Group();
        person.userData = {
            isSitting: false,
            isWalking: false,
            walkPhase: 0
        };

        // Legs - each leg is a group pivoting at hip
        function createLeg(color) {
            const legGroup = new THREE.Group();
            // Hip pivot point (group origin)
            const thigh = new THREE.Mesh(
                new THREE.CylinderGeometry(0.12, 0.1, 0.4, 8),
                new THREE.MeshLambertMaterial({ color: color })
            );
            thigh.position.y = -0.2; // Center of thigh below hip
            legGroup.add(thigh);

            const shin = new THREE.Mesh(
                new THREE.CylinderGeometry(0.1, 0.08, 0.4, 8),
                new THREE.MeshLambertMaterial({ color: color })
            );
            shin.position.y = -0.6; // Below thigh
            legGroup.add(shin);

            const foot = new THREE.Mesh(
                new THREE.BoxGeometry(0.12, 0.08, 0.24),
                new THREE.MeshLambertMaterial({ color: 0x333333 })
            );
            foot.position.y = -0.88; // Bottom of shin
            legGroup.add(foot);

            return legGroup;
        }

        const leftLeg = createLeg(legColor);
        const rightLeg = createLeg(legColor);
        leftLeg.position.x = -0.15;
        rightLeg.position.x = 0.15;
        person.add(leftLeg, rightLeg);

        // Torso
        const torso = new THREE.Mesh(
            new THREE.CylinderGeometry(0.25, 0.2, 0.5, 8),
            new THREE.MeshLambertMaterial({ color: bodyColor })
        );
        torso.position.y = 0.3; // Above hips
        person.add(torso);

        // Head
        const head = new THREE.Mesh(
            new THREE.SphereGeometry(0.2, 8, 8),
            new THREE.MeshLambertMaterial({ color: skinColor })
        );
        head.position.y = 0.75; // Top of torso
        person.add(head);

        // Nose (small hemisphere on +Z face)
        const nose = new THREE.Mesh(
            new THREE.SphereGeometry(0.04, 8, 8),
            new THREE.MeshLambertMaterial({ color: skinColor })
        );
        nose.position.set(0, 0.05, 0.18); // On front of head
        head.add(nose);

        // Arms - pivot at shoulder
        function createArm(color) {
            const armGroup = new THREE.Group();
            const upperArm = new THREE.Mesh(
                new THREE.CylinderGeometry(0.09, 0.08, 0.35, 8),
                new THREE.MeshLambertMaterial({ color: skinColor })
            );
            upperArm.position.y = -0.17; // Below shoulder
            armGroup.add(upperArm);

            const forearm = new THREE.Mesh(
                new THREE.CylinderGeometry(0.08, 0.07, 0.32, 8),
                new THREE.MeshLambertMaterial({ color: skinColor })
            );
            forearm.position.y = -0.5; // Below upper arm
            armGroup.add(forearm);

            const hand = new THREE.Mesh(
                new THREE.SphereGeometry(0.07, 8, 8),
                new THREE.MeshLambertMaterial({ color: skinColor })
            );
            hand.position.y = -0.82; // Bottom of forearm
            armGroup.add(hand);

            return armGroup;
        }

        const leftArm = createArm(bodyColor);
        const rightArm = createArm(bodyColor);
        leftArm.position.set(-0.35, 0.4, 0);
        rightArm.position.set(0.35, 0.4, 0);
        person.add(leftArm, rightArm);

        // Store references for animation
        person.userData.leftLeg = leftLeg;
        person.userData.rightLeg = rightLeg;
        person.userData.leftArm = leftArm;
        person.userData.rightArm = rightArm;

        return person;
    }

    function animatePersonWalking(person, dt) {
        const data = person.userData;
        if (data.isSitting) {
            // Sitting pose: legs bent forward, arms down
            data.leftLeg.rotation.x = -Math.PI / 2;
            data.rightLeg.rotation.x = -Math.PI / 2;
            data.leftArm.rotation.x = -Math.PI / 4;
            data.rightArm.rotation.x = -Math.PI / 4;
            data.walkPhase = 0; // Reset walk phase when sitting
        } else if (data.isWalking) {
            // Walking animation: swing legs and arms
            data.walkPhase += dt * 8;
            const legSwing = Math.sin(data.walkPhase) * 0.6;
            const armSwing = -Math.sin(data.walkPhase) * 0.5;

            data.leftLeg.rotation.x = legSwing;
            data.rightLeg.rotation.x = -legSwing;
            data.leftArm.rotation.x = armSwing;
            data.rightArm.rotation.x = -armSwing;
        } else {
            // Standing idle: reset limbs to zero rotation
            data.leftLeg.rotation.x = 0;
            data.rightLeg.rotation.x = 0;
            data.leftArm.rotation.x = 0;
            data.rightArm.rotation.x = 0;
            data.walkPhase = 0;
        }
    }

    // Expose globally for browser
    window.createPerson = createPerson;
    window.animatePersonWalking = animatePersonWalking;
})();

