    const logic = new ElevatorLogic({ floorCount: 6 });
    logic.callUp(2);

    // Fast-forward by ticking with large dt
    let totalDt = 0;
    while (logic.state !== logic.DOOR_OPENING && totalDt < 10) {
        logic.tick(0.5);
        totalDt += 0.5;
    }

    assertEqual(logic.state, logic.DOOR_OPENING);
});

