test('State machine transitions from DOOR_OPENING to DOOR_OPEN', () => {
    const logic = new ElevatorLogic({ floorCount: 6 });
    logic.callUp(2);

    // Get to DOOR_OPENING state
    let totalDt = 0;
    while (logic.state !== logic.DOOR_OPENING && totalDt < 10) {
        logic.tick(0.5);
        totalDt += 0.5;
