    const logic = new ElevatorLogic({ floorCount: 6 });
    logic.callUp(2);

    // Get through full cycle to DOOR_CLOSING
    let totalDt = 0;
    while (logic.state !== logic.DOOR_CLOSING && totalDt < 15) {
        logic.tick(0.5);
