            new THREE.MeshLambertMaterial({ color: 0x888888 })
        );
        base.position.set(shaftX + halfShaft + 0.3, floorY + 1.2, shaftZ);
        panel.add(base);

        // Up arrow (flat ShapeGeometry triangle)
        const upShape = new THREE.Shape();
        upShape.moveTo(-0.13, 0);
